INSERT INTO `t_ds_task_definition` VALUES (49, 125774974026592, 'dc1-关闭服务端', 1, '', 125774209282912, 1, 'SHELL', 0, '{\"localParams\":[],\"rawScript\":\"#!/bin/sh\\r\\n\\r\\n# 查找使用5201端口的进程PID\\r\\nPID=$(netstat -tlnp | grep :5201 | awk \'{print $7}\' | cut -d \'/\' -c 1)\\r\\n\\r\\n# 使用查找到的PID来关闭进程\\r\\nif [ -n \\\"$PID\\\" ]; then\\r\\n    kill -9 $PID\\r\\n    echo \\\"The process with PID $PID using port 5201 has been killed.\\\"\\r\\nelse\\r\\n    echo \\\"No process using port 5201 was found.\\\"\\r\\nfi\",\"resourceList\":[]}', 1, 0, 2, 'default', -1, 0, 1, 0, NULL, 0, 0, NULL, 0, 0, -1, -1, '2024-11-22 14:42:03', '2024-11-22 14:42:03');
