  `user_id` int NULL DEFAULT NULL COMMENT 'user id',
  `token` varchar(64) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NULL DEFAULT NULL COMMENT 'token',
  `expire_time` datetime NULL DEFAULT NULL COMMENT 'end time of token ',
