-- ----------------------------
-- Table structure for t_ds_alert
-- ----------------------------
DROP TABLE IF EXISTS `t_ds_alert`;
CREATE TABLE `t_ds_alert`  (
  `id` int NOT NULL AUTO_INCREMENT COMMENT 'key',
  `title` varchar(512) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NULL DEFAULT NULL COMMENT 'title',
  `sign` char(40) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NOT NULL DEFAULT '' COMMENT 'sign=sha1(content)',
  `content` text CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NULL COMMENT 'Message content (can be email, can be SMS. Mail is stored in JSON map, and SMS is string)',
  `alert_status` tinyint NULL DEFAULT 0 COMMENT '0:wait running,1:success,2:failed',
  `warning_type` tinyint NULL DEFAULT 2 COMMENT '1 workflow is successfully, 2 workflow/task is failed',
  `log` text CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NULL COMMENT 'log',
  `alertgroup_id` int NULL DEFAULT NULL COMMENT 'alert group id',
  `create_time` datetime NULL DEFAULT NULL COMMENT 'create time',
  `update_time` datetime NULL DEFAULT NULL COMMENT 'update time',
  `project_code` bigint NULL DEFAULT NULL COMMENT 'project_code',
  `workflow_definition_code` bigint NULL DEFAULT NULL COMMENT 'workflow_definition_code',
  `workflow_instance_id` int NULL DEFAULT NULL COMMENT 'workflow_instance_id',
  `alert_type` int NULL DEFAULT NULL COMMENT 'alert_type',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_status`(`alert_status` ASC) USING BTREE,
  INDEX `idx_sign`(`sign` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb3 COLLATE = utf8mb3_bin ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of t_ds_alert
-- ----------------------------

-- ----------------------------
-- Table structure for t_ds_alert_plugin_instance
-- ----------------------------
DROP TABLE IF EXISTS `t_ds_alert_plugin_instance`;
CREATE TABLE `t_ds_alert_plugin_instance`  (
  `id` int NOT NULL AUTO_INCREMENT,
  `plugin_define_id` int NOT NULL,
  `plugin_instance_params` text CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NULL COMMENT 'plugin instance params. Also contain the params value which user input in web ui.',
  `create_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `instance_name` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NULL DEFAULT NULL COMMENT 'alert instance name',
  PRIMARY KEY (`id`) USING BTREE
