  `config` text CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NULL COMMENT 'this config contains many cluster variables config',
  `description` text CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NULL COMMENT 'the details',
  `operator` int NULL DEFAULT NULL COMMENT 'operator user id',
  `create_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `cluster_name_unique`(`name` ASC) USING BTREE,
  UNIQUE INDEX `cluster_code_unique`(`code` ASC) USING BTREE
