-- ----------------------------
-- Table structure for t_ds_command
-- ----------------------------
DROP TABLE IF EXISTS `t_ds_command`;
CREATE TABLE `t_ds_command`  (
  `id` int NOT NULL AUTO_INCREMENT COMMENT 'key',
  `command_type` tinyint NULL DEFAULT NULL COMMENT 'Command type: 0 start workflow, 1 start execution from current node, 2 resume fault-tolerant workflow, 3 resume pause workflow, 4 start execution from failed node, 5 complement, 6 schedule, 7 rerun, 8 pause, 9 stop, 10 resume waiting thread',
  `workflow_definition_code` bigint NOT NULL COMMENT 'workflow definition code',
  `workflow_definition_version` int NULL DEFAULT 0 COMMENT 'workflow definition version',
  `workflow_instance_id` int NULL DEFAULT 0 COMMENT 'workflow instance id',
  `command_param` text CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NULL COMMENT 'json command parameters',
  `task_depend_type` tinyint NULL DEFAULT NULL COMMENT 'Node dependency type: 0 current node, 1 forward, 2 backward',
  `failure_strategy` tinyint NULL DEFAULT 0 COMMENT 'Failed policy: 0 end, 1 continue',
  `warning_type` tinyint NULL DEFAULT 0 COMMENT 'Alarm type: 0 is not sent, 1 workflow is sent successfully, 2 workflow is sent failed, 3 workflow is sent successfully and all failures are sent',
  `warning_group_id` int NULL DEFAULT NULL COMMENT 'warning group',
  `schedule_time` datetime NULL DEFAULT NULL COMMENT 'schedule time',
  `start_time` datetime NULL DEFAULT NULL COMMENT 'start time',
  `executor_id` int NULL DEFAULT NULL COMMENT 'executor id',
  `update_time` datetime NULL DEFAULT NULL COMMENT 'update time',
  `workflow_instance_priority` int NULL DEFAULT 2 COMMENT 'workflow instance priority: 0 Highest,1 High,2 Medium,3 Low,4 Lowest',
  `worker_group` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NULL DEFAULT NULL COMMENT 'worker group',
  `tenant_code` varchar(64) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NULL DEFAULT 'default' COMMENT 'tenant code',
  `environment_code` bigint NULL DEFAULT -1 COMMENT 'environment code',
  `dry_run` tinyint NULL DEFAULT 0 COMMENT 'dry run flag：0 normal, 1 dry run',
  `test_flag` tinyint NULL DEFAULT NULL COMMENT 'test flag：0 normal, 1 test run',
  `data_rate` int NULL DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `priority_id_index`(`workflow_instance_priority` ASC, `id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1928 CHARACTER SET = utf8mb3 COLLATE = utf8mb3_bin ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of t_ds_command
-- ----------------------------

