  `type` tinyint NOT NULL COMMENT 'data source type: 0:mysql,1:postgresql,2:hive,3:spark',
  `user_id` int NOT NULL COMMENT 'the creator id',
  `connection_params` text CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NOT NULL COMMENT 'json connection params',
  `create_time` datetime NOT NULL COMMENT 'create time',
  `update_time` datetime NULL DEFAULT NULL COMMENT 'update time',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `t_ds_datasource_name_un`(`name` ASC, `type` ASC) USING BTREE
