CREATE TABLE `t_ds_plugin_define`  (
  `id` int NOT NULL AUTO_INCREMENT,
  `plugin_name` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NOT NULL COMMENT 'the name of plugin eg: email',
  `plugin_type` varchar(63) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NOT NULL COMMENT 'plugin type . alert=alert plugin, job=job plugin',
  `plugin_params` text CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NULL COMMENT 'plugin params',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `t_ds_plugin_define_UN`(`plugin_name` ASC, `plugin_type` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2 CHARACTER SET = utf8mb3 COLLATE = utf8mb3_bin ROW_FORMAT = DYNAMIC;

