  `user_id` int NULL DEFAULT NULL COMMENT 'user id',
  `ip` varchar(45) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NULL DEFAULT NULL COMMENT 'ip',
  `last_login_time` datetime NULL DEFAULT NULL COMMENT 'last login time',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb3 COLLATE = utf8mb3_bin ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of t_ds_session
-- ----------------------------

-- ----------------------------
-- Table structure for t_ds_task_definition
-- ----------------------------
DROP TABLE IF EXISTS `t_ds_task_definition`;
CREATE TABLE `t_ds_task_definition`  (
  `id` int NOT NULL AUTO_INCREMENT COMMENT 'self-increasing id',
  `code` bigint NOT NULL COMMENT 'encoding',
  `name` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NULL DEFAULT NULL COMMENT 'task definition name',
  `version` int NOT NULL DEFAULT 1 COMMENT 'task definition version',
  `description` text CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NULL COMMENT 'description',
  `project_code` bigint NOT NULL COMMENT 'project code',
  `user_id` int NULL DEFAULT NULL COMMENT 'task definition creator id',
  `task_type` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NOT NULL COMMENT 'task type',
  `task_execute_type` int NULL DEFAULT 0 COMMENT 'task execute type: 0-batch, 1-stream',
  `task_params` longtext CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NULL COMMENT 'job custom parameters',
  `flag` tinyint NULL DEFAULT NULL COMMENT '0 not available, 1 available',
  `is_cache` tinyint NULL DEFAULT 0 COMMENT '0 not available, 1 available',
  `task_priority` tinyint NULL DEFAULT 2 COMMENT 'job priority',
  `worker_group` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NULL DEFAULT NULL COMMENT 'worker grouping',
  `environment_code` bigint NULL DEFAULT -1 COMMENT 'environment code',
  `fail_retry_times` int NULL DEFAULT NULL COMMENT 'number of failed retries',
  `fail_retry_interval` int NULL DEFAULT NULL COMMENT 'failed retry interval',
  `timeout_flag` tinyint NULL DEFAULT 0 COMMENT 'timeout flag:0 close, 1 open',
  `timeout_notify_strategy` tinyint NULL DEFAULT NULL COMMENT 'timeout notification policy: 0 warning, 1 fail',
  `timeout` int NULL DEFAULT 0 COMMENT 'timeout length,unit: minute',
  `delay_time` int NULL DEFAULT 0 COMMENT 'delay execution time,unit: minute',
  `resource_ids` text CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NULL COMMENT 'resource id, separated by comma',
  `task_group_id` int NULL DEFAULT NULL COMMENT 'task group id',
  `task_group_priority` tinyint NULL DEFAULT 0 COMMENT 'task group priority',
  `cpu_quota` int NOT NULL DEFAULT -1 COMMENT 'cpuQuota(%): -1:Infinity',
  `memory_max` int NOT NULL DEFAULT -1 COMMENT 'MemoryMax(MB): -1:Infinity',
  `create_time` datetime NOT NULL COMMENT 'create time',
  `update_time` datetime NOT NULL COMMENT 'update time',
  PRIMARY KEY (`id`, `code`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 9162 CHARACTER SET = utf8mb3 COLLATE = utf8mb3_bin ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of t_ds_task_definition
-- ----------------------------

-- ----------------------------
-- Table structure for t_ds_task_definition_log
-- ----------------------------
DROP TABLE IF EXISTS `t_ds_task_definition_log`;
CREATE TABLE `t_ds_task_definition_log`  (
  `id` int NOT NULL AUTO_INCREMENT COMMENT 'self-increasing id',
  `code` bigint NOT NULL COMMENT 'encoding',
  `name` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NULL DEFAULT NULL COMMENT 'task definition name',
  `version` int NOT NULL DEFAULT 1 COMMENT 'task definition version',
  `description` text CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NULL COMMENT 'description',
  `project_code` bigint NOT NULL COMMENT 'project code',
  `user_id` int NULL DEFAULT NULL COMMENT 'task definition creator id',
  `task_type` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NOT NULL COMMENT 'task type',
  `task_execute_type` int NULL DEFAULT 0 COMMENT 'task execute type: 0-batch, 1-stream',
  `task_params` longtext CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NULL COMMENT 'job custom parameters',
  `flag` tinyint NULL DEFAULT NULL COMMENT '0 not available, 1 available',
  `is_cache` tinyint NULL DEFAULT 0 COMMENT '0 not available, 1 available',
  `task_priority` tinyint NULL DEFAULT 2 COMMENT 'job priority',
  `worker_group` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NULL DEFAULT NULL COMMENT 'worker grouping',
  `environment_code` bigint NULL DEFAULT -1 COMMENT 'environment code',
  `fail_retry_times` int NULL DEFAULT NULL COMMENT 'number of failed retries',
  `fail_retry_interval` int NULL DEFAULT NULL COMMENT 'failed retry interval',
  `timeout_flag` tinyint NULL DEFAULT 0 COMMENT 'timeout flag:0 close, 1 open',
  `timeout_notify_strategy` tinyint NULL DEFAULT NULL COMMENT 'timeout notification policy: 0 warning, 1 fail',
  `timeout` int NULL DEFAULT 0 COMMENT 'timeout length,unit: minute',
  `delay_time` int NULL DEFAULT 0 COMMENT 'delay execution time,unit: minute',
  `resource_ids` text CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NULL COMMENT 'resource id, separated by comma',
  `operator` int NULL DEFAULT NULL COMMENT 'operator user id',
  `task_group_id` int NULL DEFAULT NULL COMMENT 'task group id',
  `task_group_priority` tinyint NULL DEFAULT 0 COMMENT 'task group priority',
  `operate_time` datetime NULL DEFAULT NULL COMMENT 'operate time',
  `cpu_quota` int NOT NULL DEFAULT -1 COMMENT 'cpuQuota(%): -1:Infinity',
  `memory_max` int NOT NULL DEFAULT -1 COMMENT 'MemoryMax(MB): -1:Infinity',
  `create_time` datetime NOT NULL COMMENT 'create time',
  `update_time` datetime NOT NULL COMMENT 'update time',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_code_version`(`code` ASC, `version` ASC) USING BTREE,
  INDEX `idx_project_code`(`project_code` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 9251 CHARACTER SET = utf8mb3 COLLATE = utf8mb3_bin ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of t_ds_task_definition_log
-- ----------------------------

-- ----------------------------
-- Table structure for t_ds_task_group
-- ----------------------------
DROP TABLE IF EXISTS `t_ds_task_group`;
CREATE TABLE `t_ds_task_group`  (
  `id` int NOT NULL AUTO_INCREMENT COMMENT 'key',
  `name` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NULL DEFAULT NULL COMMENT 'task_group name',
  `description` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NULL DEFAULT NULL,
  `group_size` int NOT NULL COMMENT 'group size',
  `use_size` int NULL DEFAULT 0 COMMENT 'used size',
  `user_id` int NULL DEFAULT NULL COMMENT 'creator id',
  `project_code` bigint NULL DEFAULT 0 COMMENT 'project code',
  `status` tinyint NULL DEFAULT 1 COMMENT '0 not available, 1 available',
  `create_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb3 COLLATE = utf8mb3_bin ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of t_ds_task_group
-- ----------------------------

-- ----------------------------
-- Table structure for t_ds_task_group_queue
-- ----------------------------
DROP TABLE IF EXISTS `t_ds_task_group_queue`;
CREATE TABLE `t_ds_task_group_queue`  (
  `id` int NOT NULL AUTO_INCREMENT COMMENT 'key',
  `task_id` int NULL DEFAULT NULL COMMENT 'taskintanceid',
  `task_name` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NULL DEFAULT NULL COMMENT 'TaskInstance name',
  `group_id` int NULL DEFAULT NULL COMMENT 'taskGroup id',
  `workflow_instance_id` int NULL DEFAULT NULL COMMENT 'workflow instance id',
  `priority` int NULL DEFAULT 0 COMMENT 'priority',
  `status` tinyint NULL DEFAULT -1 COMMENT '-1: waiting  1: running  2: finished',
  `force_start` tinyint NULL DEFAULT 0 COMMENT 'is force start 0 NO ,1 YES',
  `in_queue` tinyint NULL DEFAULT 0 COMMENT 'ready to get the queue by other task finish 0 NO ,1 YES',
  `create_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_t_ds_task_group_queue_in_queue`(`in_queue` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb3 COLLATE = utf8mb3_bin ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of t_ds_task_group_queue
-- ----------------------------

-- ----------------------------
-- Table structure for t_ds_task_instance
-- ----------------------------
DROP TABLE IF EXISTS `t_ds_task_instance`;
CREATE TABLE `t_ds_task_instance`  (
  `id` int NOT NULL AUTO_INCREMENT COMMENT 'key',
  `name` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NULL DEFAULT NULL COMMENT 'task name',
  `task_type` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NOT NULL COMMENT 'task type',
  `task_execute_type` int NULL DEFAULT 0 COMMENT 'task execute type: 0-batch, 1-stream',
  `task_code` bigint NOT NULL COMMENT 'task definition code',
  `task_definition_version` int NOT NULL DEFAULT 1 COMMENT 'task definition version',
  `workflow_instance_id` int NULL DEFAULT NULL COMMENT 'workflow instance id',
  `workflow_instance_name` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NULL DEFAULT NULL COMMENT 'workflow instance name',
  `project_code` bigint NULL DEFAULT NULL COMMENT 'project code',
  `dispatch_code` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NULL DEFAULT NULL COMMENT '调度编号',
  `dispatch_index` int NULL DEFAULT NULL COMMENT '分发索引',
  `state` tinyint NULL DEFAULT NULL COMMENT 'Status: 0 commit succeeded, 1 running, 2 prepare to pause, 3 pause, 4 prepare to stop, 5 stop, 6 fail, 7 succeed, 8 need fault tolerance, 9 kill, 10 wait for thread, 11 wait for dependency to complete',
  `submit_time` datetime NULL DEFAULT NULL COMMENT 'task submit time',
  `start_time` datetime NULL DEFAULT NULL COMMENT 'task start time',
  `end_time` datetime NULL DEFAULT NULL COMMENT 'task end time',
  `wait_time` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NULL DEFAULT NULL COMMENT '预测等待时间',
  `transfer_time` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NULL DEFAULT NULL COMMENT '预测传输时间',
  `exe_time` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NULL DEFAULT NULL COMMENT '预测运行时间',
  `completion_time` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NULL DEFAULT NULL COMMENT '预测完成时间',
  `duration` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NULL DEFAULT NULL COMMENT '真实运行时长',
  `dispatch_time` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NULL DEFAULT NULL COMMENT '分发时间',
  `host` varchar(135) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NULL DEFAULT NULL COMMENT 'host of task running on',
  `data_host` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NULL DEFAULT NULL COMMENT '数据位置',
  `thread_id` int NULL DEFAULT NULL,
  `execute_path` varchar(200) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NULL DEFAULT NULL COMMENT 'task execute path in the host',
  `log_path` longtext CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NULL COMMENT 'task log path',
  `alert_flag` tinyint NULL DEFAULT NULL COMMENT 'whether alert',
  `retry_times` int NULL DEFAULT 0 COMMENT 'task retry times',
  `pid` int NULL DEFAULT NULL COMMENT 'pid of task',
  `app_link` text CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NULL COMMENT 'yarn app id',
  `task_params` longtext CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NULL COMMENT 'job custom parameters',
  `flag` tinyint NULL DEFAULT 1 COMMENT '0 not available, 1 available',
  `is_cache` tinyint NULL DEFAULT 0 COMMENT '0 not available, 1 available',
  `cache_key` varchar(200) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NULL DEFAULT NULL COMMENT 'cache_key',
  `retry_interval` int NULL DEFAULT NULL COMMENT 'retry interval when task failed ',
  `max_retry_times` int NULL DEFAULT NULL COMMENT 'max retry times',
  `task_instance_priority` int NULL DEFAULT NULL COMMENT 'task instance priority:0 Highest,1 High,2 Medium,3 Low,4 Lowest',
  `worker_group` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NULL DEFAULT NULL COMMENT 'worker group id',
  `environment_code` bigint NULL DEFAULT -1 COMMENT 'environment code',
  `environment_config` text CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NULL COMMENT 'this config contains many environment variables config',
  `executor_id` int NULL DEFAULT NULL,
  `executor_name` varchar(64) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NULL DEFAULT NULL,
  `first_submit_time` datetime NULL DEFAULT NULL COMMENT 'task first submit time',
  `delay_time` int NULL DEFAULT 0 COMMENT 'task delay execution time',
  `var_pool` longtext CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NULL COMMENT 'var_pool',
  `task_group_id` int NULL DEFAULT NULL COMMENT 'task group id',
  `dry_run` tinyint NULL DEFAULT 0 COMMENT 'dry run flag: 0 normal, 1 dry run',
  `cpu_quota` int NOT NULL DEFAULT -1 COMMENT 'cpuQuota(%): -1:Infinity',
  `memory_max` int NOT NULL DEFAULT -1 COMMENT 'MemoryMax(MB): -1:Infinity',
  `test_flag` tinyint NULL DEFAULT NULL COMMENT 'test flag：0 normal, 1 test run',
  `key_flag` tinyint NULL DEFAULT NULL COMMENT '0:不属于关键路径，1:属于关键路径',
  `next_key_task` bigint NULL DEFAULT NULL,
  `out_result` longtext CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NULL COMMENT '输出结果',
  `resource_utilization` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NULL DEFAULT NULL COMMENT '资源利用率%',
  `receive_data_size` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NULL DEFAULT NULL COMMENT '接收数据量',
  `output_data_size` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NULL DEFAULT NULL COMMENT '输出数据量',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `workflow_instance_id`(`workflow_instance_id` ASC) USING BTREE,
  INDEX `idx_code_version`(`task_code` ASC, `task_definition_version` ASC) USING BTREE,
  INDEX `idx_cache_key`(`cache_key` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 54277 CHARACTER SET = utf8mb3 COLLATE = utf8mb3_bin ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of t_ds_task_instance
-- ----------------------------

