  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `version_UNIQUE`(`version` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2 CHARACTER SET = utf8mb3 COLLATE = utf8mb3_bin COMMENT = 'version' ROW_FORMAT = DYNAMIC;

