DROP TABLE IF EXISTS `t_ds_worker_group`;
CREATE TABLE `t_ds_worker_group`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'id',
  `name` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NOT NULL COMMENT 'worker group name',
  `addr_list` text CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NULL COMMENT 'worker addr list. split by [,]',
  `create_time` datetime NULL DEFAULT NULL COMMENT 'create time',
  `update_time` datetime NULL DEFAULT NULL COMMENT 'update time',
  `description` text CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NULL COMMENT 'description',
  `other_params_json` text CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NULL COMMENT 'other params json',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `name_unique`(`name` ASC) USING BTREE
