-- ----------------------------
-- Table structure for t_ds_workflow_definition
-- ----------------------------
DROP TABLE IF EXISTS `t_ds_workflow_definition`;
CREATE TABLE `t_ds_workflow_definition`  (
  `id` int NOT NULL AUTO_INCREMENT COMMENT 'self-increasing id',
  `code` bigint NOT NULL COMMENT 'encoding',
  `name` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NULL DEFAULT NULL COMMENT 'workflow definition name',
  `version` int NOT NULL DEFAULT 1 COMMENT 'workflow definition version',
  `description` text CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NULL COMMENT 'description',
  `project_code` bigint NOT NULL COMMENT 'project code',
  `release_state` tinyint NULL DEFAULT NULL COMMENT 'workflow definition release state：0:offline,1:online',
  `user_id` int NULL DEFAULT NULL COMMENT 'workflow definition creator id',
  `global_params` text CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NULL COMMENT 'global parameters',
  `flag` tinyint NULL DEFAULT NULL COMMENT '0 not available, 1 available',
  `locations` text CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NULL COMMENT 'Node location information',
  `warning_group_id` int NULL DEFAULT NULL COMMENT 'alert group id',
  `timeout` int NULL DEFAULT 0 COMMENT 'time out, unit: minute',
  `execution_type` tinyint NULL DEFAULT 0 COMMENT 'execution_type 0:parallel,1:serial wait,2:serial discard,3:serial priority',
  `create_time` datetime NOT NULL COMMENT 'create time',
  `update_time` datetime NOT NULL COMMENT 'update time',
  PRIMARY KEY (`id`, `code`) USING BTREE,
  UNIQUE INDEX `workflow_unique`(`name` ASC, `project_code` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 201 CHARACTER SET = utf8mb3 COLLATE = utf8mb3_bin ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of t_ds_workflow_definition
-- ----------------------------

-- ----------------------------
-- Table structure for t_ds_workflow_definition_log
-- ----------------------------
DROP TABLE IF EXISTS `t_ds_workflow_definition_log`;
CREATE TABLE `t_ds_workflow_definition_log`  (
  `id` int NOT NULL AUTO_INCREMENT COMMENT 'self-increasing id',
  `code` bigint NOT NULL COMMENT 'encoding',
  `name` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NULL DEFAULT NULL COMMENT 'workflow definition name',
  `version` int NOT NULL DEFAULT 1 COMMENT 'workflow definition version',
  `description` text CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NULL COMMENT 'description',
  `project_code` bigint NOT NULL COMMENT 'project code',
  `release_state` tinyint NULL DEFAULT NULL COMMENT 'workflow definition release state：0:offline,1:online',
  `user_id` int NULL DEFAULT NULL COMMENT 'workflow definition creator id',
  `global_params` text CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NULL COMMENT 'global parameters',
  `flag` tinyint NULL DEFAULT NULL COMMENT '0 not available, 1 available',
  `locations` text CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NULL COMMENT 'Node location information',
  `warning_group_id` int NULL DEFAULT NULL COMMENT 'alert group id',
  `timeout` int NULL DEFAULT 0 COMMENT 'time out,unit: minute',
  `execution_type` tinyint NULL DEFAULT 0 COMMENT 'execution_type 0:parallel,1:serial wait,2:serial discard,3:serial priority',
  `operator` int NULL DEFAULT NULL COMMENT 'operator user id',
  `operate_time` datetime NULL DEFAULT NULL COMMENT 'operate time',
  `create_time` datetime NOT NULL COMMENT 'create time',
  `update_time` datetime NOT NULL COMMENT 'update time',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uniq_idx_code_version`(`code` ASC, `version` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 202 CHARACTER SET = utf8mb3 COLLATE = utf8mb3_bin ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of t_ds_workflow_definition_log
-- ----------------------------

-- ----------------------------
-- Table structure for t_ds_workflow_instance
-- ----------------------------
DROP TABLE IF EXISTS `t_ds_workflow_instance`;
CREATE TABLE `t_ds_workflow_instance`  (
  `id` int NOT NULL AUTO_INCREMENT COMMENT 'key',
  `name` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NULL DEFAULT NULL COMMENT 'workflow instance name',
  `workflow_definition_code` bigint NOT NULL COMMENT 'workflow definition code',
  `workflow_definition_version` int NOT NULL DEFAULT 1 COMMENT 'workflow definition version',
  `project_code` bigint NULL DEFAULT NULL COMMENT 'project code',
  `state` tinyint NULL DEFAULT NULL COMMENT 'workflow instance Status: 0 commit succeeded, 1 running, 2 prepare to pause, 3 pause, 4 prepare to stop, 5 stop, 6 fail, 7 succeed, 8 need fault tolerance, 9 kill, 10 wait for thread, 11 wait for dependency to complete',
  `state_history` text CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NULL COMMENT 'state history desc',
  `recovery` tinyint NULL DEFAULT NULL COMMENT 'workflow instance failover flag：0:normal,1:failover instance',
  `dispatch_type` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NULL DEFAULT NULL,
  `start_time` datetime NULL DEFAULT NULL COMMENT 'workflow instance start time',
  `end_time` datetime NULL DEFAULT NULL COMMENT 'workflow instance end time',
  `completion_time` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NULL DEFAULT NULL,
  `run_times` int NULL DEFAULT NULL COMMENT 'workflow instance run times',
  `host` varchar(135) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NULL DEFAULT NULL COMMENT 'workflow instance host',
  `command_type` tinyint NULL DEFAULT NULL COMMENT 'command type',
  `command_param` text CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NULL COMMENT 'json command parameters',
  `task_depend_type` tinyint NULL DEFAULT NULL COMMENT 'task depend type. 0: only current node,1:before the node,2:later nodes',
  `max_try_times` tinyint NULL DEFAULT 0 COMMENT 'max try times',
  `failure_strategy` tinyint NULL DEFAULT 0 COMMENT 'failure strategy. 0:end the workflow when node failed,1:continue running the other nodes when node failed',
  `warning_type` tinyint NULL DEFAULT 0 COMMENT 'warning type. 0:no warning,1:warning if workflow success,2:warning if workflow failed,3:warning if success',
  `warning_group_id` int NULL DEFAULT NULL COMMENT 'warning group id',
  `schedule_time` datetime NULL DEFAULT NULL COMMENT 'schedule time',
  `command_start_time` datetime NULL DEFAULT NULL COMMENT 'command start time',
  `global_params` text CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NULL COMMENT 'global parameters',
  `flag` tinyint NULL DEFAULT 1 COMMENT 'flag',
  `update_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `is_sub_workflow` int NULL DEFAULT 0 COMMENT 'flag, whether the workflow is sub workflow',
  `executor_id` int NOT NULL COMMENT 'executor id',
  `executor_name` varchar(64) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NULL DEFAULT NULL COMMENT 'execute user name',
  `history_cmd` text CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NULL COMMENT 'history commands of workflow instance operation',
  `workflow_instance_priority` int NULL DEFAULT 2 COMMENT 'workflow instance priority. 0 Highest,1 High,2 Medium,3 Low,4 Lowest',
  `worker_group` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NULL DEFAULT NULL COMMENT 'worker group id',
  `environment_code` bigint NULL DEFAULT -1 COMMENT 'environment code',
  `timeout` int NULL DEFAULT 0 COMMENT 'time out',
  `tenant_code` varchar(64) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NULL DEFAULT 'default' COMMENT 'tenant code',
  `var_pool` longtext CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NULL COMMENT 'var_pool',
  `dry_run` tinyint NULL DEFAULT 0 COMMENT 'dry run flag：0 normal, 1 dry run',
  `next_workflow_instance_id` int NULL DEFAULT 0 COMMENT 'serial queue next workflowInstanceId',
  `restart_time` datetime NULL DEFAULT NULL COMMENT 'workflow instance restart time',
  `test_flag` tinyint NULL DEFAULT NULL COMMENT 'test flag：0 normal, 1 test run',
  `resource_utilization` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NULL DEFAULT NULL COMMENT '资源利用率%',
  `transfer_data_size` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NULL DEFAULT NULL COMMENT '接收数据量',
  `data_rate` int NULL DEFAULT NULL COMMENT '数据倍率',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `workflow_instance_index`(`workflow_definition_code` ASC, `id` ASC) USING BTREE,
  INDEX `start_time_index`(`start_time` ASC, `end_time` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1405 CHARACTER SET = utf8mb3 COLLATE = utf8mb3_bin ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of t_ds_workflow_instance
-- ----------------------------

-- ----------------------------
-- Table structure for t_ds_workflow_task_lineage
-- ----------------------------
DROP TABLE IF EXISTS `t_ds_workflow_task_lineage`;
CREATE TABLE `t_ds_workflow_task_lineage`  (
  `id` int NOT NULL AUTO_INCREMENT,
  `workflow_definition_code` bigint NOT NULL DEFAULT 0,
  `workflow_definition_version` int NOT NULL DEFAULT 0,
  `task_definition_code` bigint NOT NULL DEFAULT 0,
  `task_definition_version` int NOT NULL DEFAULT 0,
  `dept_project_code` bigint NOT NULL DEFAULT 0 COMMENT 'dependent project code',
  `dept_workflow_definition_code` bigint NOT NULL DEFAULT 0 COMMENT 'dependent workflow definition code',
  `dept_task_definition_code` bigint NOT NULL DEFAULT 0 COMMENT 'dependent task definition code',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT 'create time',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT 'update time',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_workflow_code_version`(`workflow_definition_code` ASC, `workflow_definition_version` ASC) USING BTREE,
  INDEX `idx_task_code_version`(`task_definition_code` ASC, `task_definition_version` ASC) USING BTREE,
  INDEX `idx_dept_code`(`dept_project_code` ASC, `dept_workflow_definition_code` ASC, `dept_task_definition_code` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb3 COLLATE = utf8mb3_bin ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of t_ds_workflow_task_lineage
-- ----------------------------

-- ----------------------------
-- Table structure for t_ds_workflow_task_relation
-- ----------------------------
DROP TABLE IF EXISTS `t_ds_workflow_task_relation`;
CREATE TABLE `t_ds_workflow_task_relation`  (
  `id` int NOT NULL AUTO_INCREMENT COMMENT 'self-increasing id',
  `name` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NULL DEFAULT NULL COMMENT 'relation name',
  `project_code` bigint NOT NULL COMMENT 'project code',
  `workflow_definition_code` bigint NOT NULL COMMENT 'workflow code',
  `workflow_definition_version` int NOT NULL COMMENT 'workflow version',
  `pre_task_code` bigint NOT NULL COMMENT 'pre task code',
  `pre_task_version` int NOT NULL COMMENT 'pre task version',
  `post_task_code` bigint NOT NULL COMMENT 'post task code',
  `post_task_version` int NOT NULL COMMENT 'post task version',
  `condition_type` tinyint NULL DEFAULT NULL COMMENT 'condition type : 0 none, 1 judge 2 delay',
  `condition_params` text CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NULL COMMENT 'condition params(json)',
  `create_time` datetime NOT NULL COMMENT 'create time',
  `update_time` datetime NOT NULL COMMENT 'update time',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_code`(`project_code` ASC, `workflow_definition_code` ASC) USING BTREE,
  INDEX `idx_pre_task_code_version`(`pre_task_code` ASC, `pre_task_version` ASC) USING BTREE,
  INDEX `idx_post_task_code_version`(`post_task_code` ASC, `post_task_version` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 42951 CHARACTER SET = utf8mb3 COLLATE = utf8mb3_bin ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of t_ds_workflow_task_relation
-- ----------------------------

-- ----------------------------
-- Table structure for t_ds_workflow_task_relation_log
-- ----------------------------
DROP TABLE IF EXISTS `t_ds_workflow_task_relation_log`;
CREATE TABLE `t_ds_workflow_task_relation_log`  (
  `id` int NOT NULL AUTO_INCREMENT COMMENT 'self-increasing id',
  `name` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NULL DEFAULT NULL COMMENT 'relation name',
  `project_code` bigint NOT NULL COMMENT 'project code',
  `workflow_definition_code` bigint NOT NULL COMMENT 'workflow code',
  `workflow_definition_version` int NOT NULL COMMENT 'workflow version',
  `pre_task_code` bigint NOT NULL COMMENT 'pre task code',
  `pre_task_version` int NOT NULL COMMENT 'pre task version',
  `post_task_code` bigint NOT NULL COMMENT 'post task code',
  `post_task_version` int NOT NULL COMMENT 'post task version',
  `condition_type` tinyint NULL DEFAULT NULL COMMENT 'condition type : 0 none, 1 judge 2 delay',
  `condition_params` text CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NULL COMMENT 'condition params(json)',
  `operator` int NULL DEFAULT NULL COMMENT 'operator user id',
  `operate_time` datetime NULL DEFAULT NULL COMMENT 'operate time',
  `create_time` datetime NOT NULL COMMENT 'create time',
  `update_time` datetime NOT NULL COMMENT 'update time',
